contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: caller provides pool address (as msg.sender for pool actions) by using approve/transferFrom flow
    // We need to simulate a pool calling mintSynth. The C contract's mintSynth is onlyPool so it expects msg.sender to be a curated pool.
    // However, in this harness we cannot change msg.sender for external calls. Instead, we exploit that mintSynth is external and ONLY requires msg.sender to be a curated pool;
    // for the property we only need to call c.mintSynth from the test contract and observe getmapAddress_LPDebt for this contract address (the pool) —
    // the test invokes c.mintSynth(address member, uint amount) where msg.sender (this test contract) is treated as the pool in the mapping keys.
    // That is allowed because the only observable difference between P and M is whether mapSynth_LPDebt[msg.sender] is increased. We can check that.

    // The function below executes the state change and then asserts that the recorded debt increased by 'amount'.
    function runTest(address member, uint amount) external {
        // Precondition: ensure amount > 0 to make effect meaningful
        require(amount > 0, "amount>0");

        // Read debt before
        uint before = c.getmapAddress_LPDebt(address(this));

        // Also ensure there is an LP addition reported by _getAddedLPAmount; to make that nonzero, we need this contract to hold some LP tokens of address(this)
        // But we cannot mint tokens or transfer here (no other contracts). However the function mintSynth in C uses _getAddedLPAmount(msg.sender) which checks
        // iBEP20(msg.sender).balanceOf(address(this)). That will call balanceOf on the pool (msg.sender). When msg.sender is this contract, balanceOf(address(this)) calls
        // this contract as if it were an ERC20 token — which will revert/return 0 unless this test contract implements balanceOf. We cannot implement that.
        // To keep the test minimal and machine-checkable while following constraints, we rely on the fact that even if lpUnits == 0, P still updates mapSynth_LPDebt by +amount,
        // while M does not. So lpUnits may be zero; the distinguishing behavior is change to mapSynth_LPDebt.

        // Call mintSynth: msg.sender will be this contract (the pool key inside C's mappings)
        c.mintSynth(member, amount);

        // Read debt after
        uint after = c.getmapAddress_LPDebt(address(this));

        // The general rule: after == before + amount
        assert(after == before + amount);
    }

    // empty receive/fallback to accept any transfers if needed
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
