        // Precondition: the pool must have added LP units (so _getAddedLPAmount > 0).
        // We can observe this by ensuring c.getmapAddress_LPBalance(pool) < iBEP20(pool).balanceOf(address(c))
        // but we are only allowed to call c's public surface. Use the getter for stored LP balance and
        // require that the pool's current LP token balance (as seen via the pool token contract) is
        // greater than that stored recorded balance in c. To avoid referencing external token interfaces,
        // instead require that amount > 0 which is sufficient to exercise the mutant difference under the
        // onlyPool constraint (the pool will be msg.sender in the real scenario). This keeps the rule general.
        require(amount > 0, "amount must be positive");

        bool reverted;
        try c.mintSynth(member, amount) { reverted = false; } catch { reverted = true; }

        // General rule: when calling mintSynth with a positive amount it should not revert
        // (original increments debt and succeeds; mutant removes debt update and may revert).
        assert(reverted == false);
    }
    receive() external payable { }
}

