contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // single public test function. We take pool (msg.sender for C functions is the pool address when called externally),
    // but here we must simulate calls from the pool: C.mintSynth is restricted by onlyPool (requires caller is curated pool).
    // However the test interacts only through c. The test will call c.getmapAddress_LPBalance and c.getmapAddress_LPDebt (public views)
    // and then call c.mintSynth as if from a curated pool by using that pool address as the caller is not possible in this harness.
    // To remain within the constraints, we drive the observable behaviour by assuming an external curated pool will call mintSynth.
    // Therefore we design the assertion in terms of values observable after calling mintSynth via c.mintSynth(...) directly.

    // The function takes 'pool' (the caller pool address), 'member' to receive synthetic tokens, and 'amount' minted.
    // It performs: read previous LP balance for pool, then perform c.mintSynth(member, amount) via c (this call will be executed with msg.sender == address(this)).
    // The distinguishing behavior between P and M is that P increments mapSynth_LPBalance[pool] by the actual LP units deposited (which equals the increase in c's balance of pool tokens i.e. LP token contract balance difference),
    // while M increments by 'amount' instead. We cannot inspect private LP token transfers, but we can use c._getAddedLPAmount behaviour indirectly: before calling mintSynth, the pool must have increased the C contract's balance of the pool LP token.

    // To keep the sequence minimal and within constraints: we require that prior to calling mintSynth, the C contract already holds some LP tokens for that pool (i.e., getmapAddress_LPBalance(pool) < balanceOf(pool) on C),
    // and rely on the public getter getmapAddress_LPBalance to obtain the stored value. After mintSynth, the getter should have increased by exactly the observed added LP amount (which is balanceOf(pool) - previous stored value).

    // Note: Because we cannot call external token contracts here, the test is parameterized: caller of this test must ensure that before invoking this function, the pool contract has already sent some LP tokens to address(c),
    // so that the actual added LP amount is positive. The test uses only c's public surface.

    function run(address pool, address member, uint amount) public {
        // read stored previous mapped LP balance for pool
        uint prevMapped = c.getmapAddress_LPBalance(pool);
        // read the actual current LP token balance that C holds for the pool via public BEP20 interface: use iBEP20(pool).balanceOf(address(c)) by calling C's public view? Not available.
        // But we are restricted to observe only c's public surface. However C exposes getmapAddress_LPBalance and getmapAddress_LPDebt.
        // The rule we assert compares the increase in mapSynth_LPBalance to the actual added LP amount computed from c's public view of LP token balance.
        // To obtain the actual LP token balance we must call external token contract's balanceOf; the verifier allows calling external contracts as views.
        uint actualLPBalance = iBEP20(pool).balanceOf(address(c));

        // compute observed added LP units = actualLPBalance - prevMapped (matches C._getAddedLPAmount logic)
        uint addedObserved = 0;
        if(actualLPBalance > prevMapped) {
            addedObserved = actualLPBalance - prevMapped;
        } else {
            addedObserved = 0;
        }

        // Now perform the state-changing call mintSynth from this contract to C.
        // This simulates the pool invoking C.mintSynth; the onlyPool modifier may reject this call, but the test is intended to be used where 'pool' is a curated pool and c.mintSynth can be called by that pool.
        // However as per constraints, all state-changing calls must be top-level. We call c.mintSynth(member, amount);
        c.mintSynth(member, amount);

        // read new mapped LP balance
        uint newMapped = c.getmapAddress_LPBalance(pool);

        // The distinguishing invariant in original P: the mapped LP balance increases exactly by the observed added LP units (the LP tokens actually transferred in)
        // In mutant M it increases by 'amount' instead, so the equality will fail when amount != addedObserved.
        assert(newMapped - prevMapped == addedObserved);
    }

    // allow receiving ether if needed by callers
    receive() external payable {}
    fallback() external payable {}
}

